<?php if (session_status() === PHP_SESSION_NONE) session_start(); function cc_pago_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} $c=$data['contrato']??[]; $metodos=$data['metodos']??[]; ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pago y contratación | CreaContable</title><link rel="stylesheet" href="<?php echo URLROOT; ?>/public/css/style.css"><link rel="stylesheet" href="<?php echo URLROOT; ?>/public/css/theme.css"><style>
:root{--pay-accent:#f5a623;--pay-bg:#f2f5fa;--pay-surface:#fff;--pay-panel:#f8fafc;--pay-border:#d8e1ed;--pay-text:#233149;--pay-muted:#61718a;--pay-input:#fff}
*{box-sizing:border-box}html,body.cc-payment-page{margin:0!important;min-height:100%;width:100%!important;font-family:Inter,"Segoe UI",Arial,sans-serif;background:var(--pay-bg)!important;color:var(--pay-text)!important;font-size:16px!important;line-height:1.55}
.payment-wrap{display:block!important;position:relative;width:min(1100px,calc(100% - 40px))!important;max-width:1100px!important;min-width:0!important;margin:32px auto 64px!important;padding:0!important;transform:none!important}
.payment-card{display:block;width:100%;min-width:0;background:var(--pay-surface);border:1px solid var(--pay-border);border-radius:20px;padding:clamp(20px,3vw,38px);margin:0 0 20px;box-shadow:0 16px 45px rgba(28,45,73,.09);color:var(--pay-text)}
.payment-head{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(240px,.8fr);gap:24px;align-items:center;padding-bottom:24px;border-bottom:1px solid var(--pay-border);margin-bottom:24px}
.payment-summary{background:linear-gradient(145deg,#eef4ff,#fff9ed);border:1px solid #d9e3f2;border-radius:16px;padding:22px;min-width:0}.payment-eyebrow{font-size:.8rem;letter-spacing:.09em;font-weight:800;color:#a86108;margin:0 0 8px}.payment-head h1{font-size:clamp(1.65rem,3vw,2.25rem);line-height:1.2;margin:0 0 12px;color:var(--pay-text)}.payment-head h2{font-size:1.25rem;margin:0 0 8px;overflow-wrap:anywhere}.payment-muted{color:var(--pay-muted)!important}.payment-price{font-size:clamp(1.5rem,3vw,2rem);font-weight:850;color:#b96b08;margin:8px 0}.payment-step{display:flex;align-items:center;gap:12px;margin:26px 0 14px}.payment-step h3{font-size:1.2rem;margin:0;color:var(--pay-text)}.payment-step-number{display:grid;place-items:center;flex:0 0 38px;width:38px;height:38px;border-radius:12px;background:var(--pay-accent);color:#241707;font-weight:900}
.payment-methods-panel{width:100%;padding:22px;background:var(--pay-panel);border:1px solid var(--pay-border);border-radius:16px}.payment-section-note{text-align:center;color:var(--pay-muted);margin:0 0 16px}.payment-methods{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;width:100%;margin:18px 0 4px}.payment-method{display:flex;flex-direction:column;align-items:flex-start;gap:9px;min-width:0;min-height:150px;padding:20px;border:1px solid var(--pay-border);border-radius:14px;background:var(--pay-surface);cursor:pointer;overflow-wrap:anywhere;transition:border-color .18s,box-shadow .18s,transform .18s}.payment-method:hover{border-color:#d99a2b;transform:translateY(-2px)}.payment-method:has(input:checked){border-color:var(--pay-accent);box-shadow:0 0 0 2px #f5a62330;background:#fffaf0}.payment-method input{width:18px;height:18px;accent-color:var(--pay-accent);margin:0}.payment-method strong{font-size:1.05rem;color:var(--pay-text)}.payment-method p{margin:0;color:var(--pay-muted);overflow-wrap:anywhere}.payment-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 18px}.payment-field{display:flex;flex-direction:column;gap:7px;margin:12px 0;min-width:0}.payment-field label{font-size:.92rem;font-weight:700;color:var(--pay-text)}.payment-field input,.payment-field textarea,.payment-field select{display:block;width:100%;min-width:0;padding:12px 13px;border-radius:10px;border:1px solid #cbd5e1;background:var(--pay-input);color:var(--pay-text);font:inherit}.payment-field textarea{min-height:90px}.payment-field input:focus,.payment-field textarea:focus{outline:3px solid #f5a62330;border-color:#d99a2b}.payment-wide{grid-column:1/-1}.payment-btn{display:inline-flex;justify-content:center;align-items:center;gap:8px;background:var(--pay-accent);color:#241707;padding:13px 18px;border:0;border-radius:10px;font-weight:800;text-decoration:none;cursor:pointer;margin-top:12px}.payment-submit{width:100%;font-size:1rem;padding:15px}.payment-notice{background:#fff7e8;border:1px solid #f0d29b;border-radius:12px;padding:15px;margin:16px 0;color:#69470c}.payment-back{margin-top:14px}.payment-wrap p{overflow-wrap:anywhere}
body.theme-dark.cc-payment-page{--pay-bg:#0b0f16;--pay-surface:#171e2a;--pay-panel:#111722;--pay-border:#303b4e;--pay-text:#edf2fa;--pay-muted:#b1bdd0;--pay-input:#0d131d;background:var(--pay-bg)!important;color:var(--pay-text)!important}.theme-dark .payment-card{background:var(--pay-surface)!important;color:var(--pay-text)!important;border-color:var(--pay-border)!important}.theme-dark .payment-summary{background:linear-gradient(145deg,#1a2b45,#282318);border-color:#394b66}.theme-dark .payment-head h1,.theme-dark .payment-head h2,.theme-dark .payment-step h3,.theme-dark .payment-method strong,.theme-dark .payment-field label{color:var(--pay-text)!important}.theme-dark .payment-method{background:#151c28;border-color:var(--pay-border)}.theme-dark .payment-method:has(input:checked){background:#382b15;border-color:#f5a623}.theme-dark .payment-field input,.theme-dark .payment-field textarea,.theme-dark .payment-field select{background:var(--pay-input)!important;color:var(--pay-text)!important;border-color:#43516a!important}.theme-dark .payment-notice{background:#342916;border-color:#795b22;color:#ffe6af}.theme-dark .payment-price{color:#ffc45d}.theme-dark .payment-eyebrow{color:#ffc45d}
@media(max-width:760px){.payment-wrap{width:calc(100% - 24px)!important;margin:14px auto 40px!important}.payment-head{grid-template-columns:1fr}.payment-methods{grid-template-columns:repeat(2,minmax(0,1fr))}.payment-card{padding:18px}.payment-methods-panel{padding:14px}}
@media(max-width:520px){.payment-methods,.payment-form-grid{grid-template-columns:1fr}.payment-wide{grid-column:auto}.payment-method{min-height:0;padding:16px}}
</style></head><body class="cc-payment-page"><main class="payment-wrap"><section class="payment-card"><div class="payment-head"><div><p class="payment-eyebrow">CENTRO DE SERVICIOS PROFESIONALES</p><h1 style="margin:0 0 10px">💳 Contratar y registrar el pago</h1><h2 style="margin:0"><?php echo cc_pago_h($c['titulo']??'Servicio'); ?></h2><p class="payment-muted">Selecciona cómo pagar y registra la transferencia para que el contador pueda revisarla.</p></div><div class="payment-summary"><span class="payment-muted">Total del servicio</span><p class="payment-price" style="margin:8px 0">$<?php echo number_format((float)($c['monto']??0),0,',','.'); ?> <?php echo cc_pago_h($c['moneda']??'COP'); ?></p><span class="payment-muted">Estado del pago:</span> <strong><?php echo cc_pago_h($c['estado_pago']??'pendiente'); ?></strong></div></div><?php if(!empty($_SESSION['marketplace_msg'])): ?><div class="payment-notice"><?php echo cc_pago_h($_SESSION['marketplace_msg']); unset($_SESSION['marketplace_msg']); ?></div><?php endif; ?>
<?php if(empty($metodos)): ?><div class="payment-notice">Este contador aún no ha configurado métodos de pago para este servicio. Contacta al contador antes de transferir.</div><?php else: ?><form method="post" action="<?php echo URLROOT.'/marketplace/pago/'.(int)$c['id']; ?>"><div class="payment-step"><span class="payment-step-number">1</span><h3 style="margin:0">Elige tu método de pago</h3></div><div class="payment-methods-panel"><p class="payment-section-note">Selecciona una de las formas de pago que acepta este contador.</p><div class="payment-methods"><?php foreach($metodos as $i=>$m): ?><label class="payment-method"><input type="radio" name="metodo_pago" value="<?php echo cc_pago_h($m['metodo']); ?>" required> <strong><?php echo cc_pago_h($m['metodo']); ?></strong><p>Cuenta: <?php echo cc_pago_h($m['datos_cuenta']); ?></p><?php if(!empty($m['titular'])): ?><p>Titular: <?php echo cc_pago_h($m['titular']); ?></p><?php endif; ?></label><?php endforeach; ?></div></div><p class="payment-muted">Realiza la transferencia por el canal indicado. Luego registra los datos del comprobante. El envío no equivale a una confirmación bancaria.</p><div class="payment-step"><span class="payment-step-number">2</span><h3 style="margin:0">Registra los datos de la transferencia</h3></div><p class="payment-section-note">Usa los datos del comprobante para que el contador pueda identificar el pago.</p><div class="payment-form-grid"><div class="payment-field"><label>Referencia o número de transacción *</label><input name="referencia_pago" maxlength="180" required></div><div class="payment-field"><label>Fecha de transferencia *</label><input type="date" name="fecha_pago" required max="<?php echo date('Y-m-d'); ?>"></div><div class="payment-field"><label>Banco o entidad de origen *</label><input name="banco_origen" maxlength="120" required></div><div class="payment-field"><label>Enlace al comprobante (opcional)</label><input type="url" name="comprobante_url" maxlength="255" placeholder="https://..."><small class="payment-muted">Sube el comprobante a un lugar privado y pega un enlace seguro; no publiques documentos bancarios en sitios abiertos.</small></div><div class="payment-field payment-wide"><label>Notas adicionales (opcional)</label><textarea name="notas_pago" maxlength="2000"></textarea></div></div><button class="payment-btn payment-submit" type="submit">Enviar comprobante al contador →</button></form><?php endif; ?><div class="payment-notice"><strong>Importante:</strong> el estado será «procesando / pendiente de verificación». El contador debe comprobar el ingreso en su cuenta antes de considerar el servicio pagado y comenzar el trabajo. Esta función registra comprobantes manuales; no es una pasarela de pago automática.</div><a class="payment-btn payment-back" href="<?php echo URLROOT; ?>/marketplace/servicios">Volver al Centro de servicios</a></section></main><script src="<?php echo URLROOT; ?>/public/js/theme.js"></script></body></html>